"""Original infectious-disease chapter: fever, diagnostic strategy and specimen interpretation."""
from qbank_authoring import question,ref,finalize
FU=ref('EANM Consensus: FDG PET/CT in Fever and Inflammation of Unknown Origin, 2024','https://pmc.ncbi.nlm.nih.gov/articles/PMC11224117/')
LA=ref('IDSA/ASM: Microbiology Laboratory Utilization Guide, 2024','https://www.idsociety.org/practice-guideline/laboratory-diagnosis-of-infectious-diseases/')
IC=ref('SCCM/IDSA: Evaluation of New Fever in Adult ICU Patients','https://www.idsociety.org/practice-guideline/new-fever-in-critically-ill-patients/')
TR=ref('CDC Yellow Book: Post-Travel Evaluation of the Ill Traveler','https://www.cdc.gov/yellow-book/hcp/post-travel-evaluation/post-travel-evaluation-of-the-ill-traveler.html')
MA=ref('CDC: Evaluation and Diagnosis of Malaria','https://www.cdc.gov/malaria/hcp/clinical-guidance/evaluation-and-diagnosis.html')
NF=ref('Consensus Guidelines for Initial Management of Neutropenic Fever, 2025','https://onlinelibrary.wiley.com/doi/10.1111/imj.70248')
GC=ref('ACR/VF Guideline: Giant Cell Arteritis and Takayasu Arteritis','https://doi.org/10.1002/acr.24632')
BR=ref('CDC: Clinical Overview of Brucellosis','https://www.cdc.gov/brucellosis/hcp/clinical-overview/')
QF=ref('CDC: Clinical and Laboratory Diagnosis of Q Fever','https://www.cdc.gov/q-fever/hcp/diagnosis-testing/index.html')
TY=ref('CDC: Clinical Guidance for Typhoid and Paratyphoid Fever','https://www.cdc.gov/typhoid-fever/hcp/clinical-guidance/index.html')
SP=ref('BSH: Infection Prevention and Treatment in Absent or Hypofunctional Spleen','https://cms.b-s-h.org.uk/guidelines/guidelines/prevention-and-treatment-of-infection-in-patients-with-an-absent-or-hypofunctional-spleen')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('A stable immunocompetent adult has prolonged documented fever and an unrevealing initial evaluation. Which next strategy is most useful?', 'Repeat the exposure history and focused examination, then pursue investigations directed by potential diagnostic clues',[
 ('Order every available serology regardless of exposure probability','Indiscriminate testing increases false-positive findings.'),('Begin broad antibiotics and glucocorticoids routinely before obtaining informative specimens','In a stable patient this can obscure the diagnosis and create harm.'),('Classify the illness as bacterial solely because fever has persisted','Inflammation, malignancy and other causes remain possible.')],
 'Prolonged fever needs an iterative diagnostic process', '**A new examination or exposure detail can redirect the differential.**',['Review travel, animals, occupation, medicines, devices and immune status.','Look again for lymphadenopathy, vascular signs, rash and focal pain.'], '**Use targeted microbiology, imaging and tissue sampling.**',['The approach differs in shock, neutropenia or threatened organ function.','Track objective fever and the evolution of diagnostic clues.'],[['Stable prolonged fever','Iterative clue-directed evaluation'],['Unstable patient','Urgent treatment and source evaluation'],['Broad panels','More incidental false positives']],[FU,LA],style='clinical_scenario')
q('Which grouping best captures the principal etiological categories considered in classical fever of unknown origin?', 'Infections, noninfectious inflammatory disease, malignancy and miscellaneous causes',[
 ('Bacterial infections and viral infections only','This excludes important noninfectious causes.'),('Autoimmune disease only once the first culture is negative','Negative cultures do not exclude infection or malignancy.'),('Malignancy alone whenever weight loss is present','Weight loss is not specific to cancer.')],
 'FUO is a diagnostic syndrome rather than a single disease', '**The relative frequency of causes varies by geography and referral population.**',['Tuberculosis and occult focal infection remain relevant in appropriate settings.','Vasculitis and hematological malignancy can produce similar systemic inflammation.'], '**Keep the differential broad but the testing purposeful.**',['A diagnosis may remain unresolved after a thorough evaluation.','Follow-up can reveal a previously absent clue.'],[['Infectious','Exposure and site-directed evaluation'],['Inflammatory','Vasculitis and systemic inflammation'],['Malignant','Especially hematological disease']],[FU])
q('In an undiagnosed patient with persistent inflammatory fever after an appropriate initial evaluation, what is the main value of FDG PET/CT?', 'Localizing metabolically active sites that can guide further imaging or tissue sampling',[
 ('Definitively distinguishing infection from cancer by uptake intensity alone','Both can be FDG-avid.'),('Replacing every biopsy with a definitive molecular diagnosis','PET does not provide histological identity.'),('Proving bacterial infection whenever uptake is present','Inflammatory and malignant uptake are also common.')],
 'Metabolic localization and etiological confirmation are different steps', '**FDG PET/CT can identify a useful biopsy target.**',['Vascular, nodal, bone and other inflammatory patterns can be informative.','Interpret the scan with pretest probability and prior investigations.'], '**Confirm the cause with appropriate targeted tests.**',['Glucocorticoids can reduce inflammatory uptake and affect yield.','A negative scan is interpreted alongside the clinical course rather than as a universal exclusion.'],[['PET/CT','Localizes activity'],['Biopsy or microbiology','Determines cause'],['Limitation','Uptake is not disease-specific']],[FU])
q('A patient with prolonged fever has an accessible enlarged lymph node and concern for lymphoma or tuberculosis. How should the biopsy specimen be planned?', 'Coordinate pathology and microbiology beforehand so suitable separate material is available for histology, culture and indicated molecular studies',[
 ('Place all tissue in formalin and request viable mycobacterial culture later','Formalin compromises culture viability.'),('Send only a surface swab of intact skin over the node','It does not sample the lesion.'),('Perform repeated empirical treatment courses before considering tissue','This can delay diagnosis and reduce microbiological yield.')],
 'A valuable specimen can be lost through incorrect handling', '**Different diagnostic tests require different specimen conditions.**',['Histology needs appropriate fixation and architecture.','Culture requires suitable unfixed material and transport.'], '**Discuss the differential before the procedure.**',['Allocate tissue for flow cytometry when lymphoma is suspected.','Use safe technique and avoid unnecessary delay in an unstable patient.'],[['Histology','Architecture and appropriate fixation'],['Culture','Viable unfixed specimen'],['Planning','Pathology and microbiology coordination']],[LA],style='clinical_scenario')
q('Before antibiotics, what most strongly improves adult blood-culture sensitivity when bacteremia is suspected?', 'Adequate blood volume collected in appropriately obtained culture sets',[
 ('Collecting only a tiny sample from every bottle','Low volume reduces sensitivity.'),('Waiting for the highest fever spike before drawing any cultures','This can delay diagnosis and is not necessary.'),('Using a single bottle as a universal replacement for multiple sets','This reduces yield and makes contamination harder to interpret.')],
 'Blood volume is a major determinant of culture yield', '**Follow the laboratory’s adult set-volume and bottle instructions.**',['Adults usually need multiple appropriately collected sets.','Aseptic collection reduces misleading contamination.'], '**Collect before antimicrobials when feasible without delaying urgent care.**',['Record the site and time of collection.','Children require weight-appropriate volumes rather than adult volumes.'],[['Volume','Major yield determinant'],['Asepsis','Reduces contamination'],['Timing','Before antibiotics when safely feasible']],[LA])
q('A febrile patient has one of four blood-culture bottles positive for a common skin coagulase-negative staphylococcus and no implanted device. Which interpretation is best?', 'Assess possible contamination using the organism, collection pattern, repeat cultures and clinical context',[
 ('Any positive bottle proves sustained bacteremia','Contamination is possible.'),('All coagulase-negative staphylococci are harmless contaminants','They can cause true infection, especially with prosthetic material.'),('Bottle count alone definitively rules out infection','Clinical and microbiological context remains necessary.')],
 'Culture interpretation is probabilistic rather than binary', '**Skin commensals can represent contamination or genuine infection.**',['Concordant separate sets and device risk can increase concern for true bacteremia.','Time to positivity may provide additional context.'], '**Repeat appropriate cultures when clinical suspicion persists.**',['Avoid unnecessary prolonged treatment for a contaminant.','Do not dismiss a compatible device-related infection because the organism is a skin commensal.'],[['Single commensal isolate','Possible contamination'],['Multiple concordant sets','Greater concern for true infection'],['Device','Changes pretest probability']],[LA],style='clinical_scenario')
q('Why does a negative blood culture after several antibiotic doses fail to exclude bacterial infection?', 'Antibiotic exposure can reduce viable organism recovery, and some infections are not continuously bacteremic',[
 ('Antibiotics always make cultures more sensitive','They can suppress growth.'),('Every bacterial infection continuously seeds blood','Many focal infections do not.'),('A negative culture proves a noninfectious diagnosis','It must be interpreted with sampling and clinical context.')],
 'A test result depends on specimen timing and biology', '**Prior therapy can reduce conventional culture yield.**',['Deep focal infections may require direct sampling.','Fastidious organisms may need specialized methods.'], '**Reconsider the suspected site and diagnostic method.**',['Do not stop necessary emergency treatment merely to improve culture yield.','Use validated molecular or serological testing when indicated.'],[['Prior antibiotics','May suppress growth'],['Focal infection','May need site sampling'],['Negative culture','Does not exclude all bacterial disease']],[LA])
q('A critically ill patient has a low procalcitonin but a convincing clinical syndrome of septic shock. What is the best interpretation?', 'A low value must not delay appropriate emergency antimicrobial treatment and source assessment',[
 ('It excludes bacterial sepsis with certainty','Sensitivity is incomplete and timing matters.'),('It proves a viral infection requiring no other assessment','It does not establish a viral etiology.'),('It replaces cultures and imaging','Biomarkers do not identify every organism or source.')],
 'Biomarkers support rather than replace clinical decisions', '**Early or localized bacterial disease can have a low procalcitonin.**',['Noninfectious conditions can also elevate it.','Use pretest probability and the whole clinical picture.'], '**Treat a high-risk clinical emergency promptly.**',['Obtain suitable specimens without creating harmful delay.','Serial markers may support later decisions in an appropriate pathway.'],[['Low value','Not universal exclusion'],['High value','Not organism identification'],['Shock','Urgent clinical management']],[IC],style='clinical_scenario')
q('A febrile traveler recently returned from a malaria-endemic region. The first smear is negative but suspicion remains high. What is the best next diagnostic step?', 'Repeat thick and thin smears every 12–24 hours for a total of three sets while continuing urgent clinical assessment',[
 ('Exclude malaria permanently after the first smear','Low parasitemia can initially be missed.'),('Wait for a periodic 48-hour fever pattern before retesting','Classic periodicity may be absent and delay can be dangerous.'),('Use a single antibody test as the acute rule-out test','Serology is not the appropriate acute diagnostic strategy.')],
 'Malaria must be considered promptly in compatible fever', '**Microscopy assesses species and parasite density.**',['Early low-density infection can produce an initially negative smear.','Rapid tests do not eliminate the need for appropriate microscopy.'], '**Do not let serial testing delay care for severe illness.**',['Arrange urgent treatment or referral when severe malaria is suspected.','Report the travel itinerary and any prophylaxis use.'],[['First smear negative','Repeat if suspicion remains'],['Interval','12–24 hours'],['Total','Three sets in the CDC pathway']],[MA],style='clinical_scenario')
q('Which history detail most usefully changes the infectious differential in a febrile returned traveler?', 'The precise itinerary, dates, activities, exposures and incubation interval',[
 ('The country of residence without the route and dates of travel','It does not adequately define where or when exposure occurred.'),('An incubation interval calculated only from the return date','Exposure may have occurred much earlier during the trip.'),('The fever pattern and antipyretic response without an exposure history','These are less specific than a compatible exposure and incubation interval.')],
 'Exposure probability and incubation time narrow the differential', '**Ask about fresh water, animals, insects, food, sexual contact and health care.**',['Illness after travel can still be an ordinary community infection.','Vaccination and prophylaxis reduce selected risks but do not exclude every infection.'], '**Identify high-consequence diagnoses early.**',['Assess malaria and transmissible special pathogens when the itinerary supports them.','Use appropriate infection-control precautions while investigating.'],[['Place','Geographic exposure'],['Time','Incubation compatibility'],['Activity','Mechanism of acquisition']],[TR])
q('A traveler has fever and marked eosinophilia after freshwater exposure. Which infectious category deserves particular consideration?', 'Tissue-invasive helminth infection, with testing directed by exposure and timing',[
 ('Uncomplicated enteric fever as the characteristic eosinophilic syndrome','Marked eosinophilia is not its typical signature.'),('Malaria as the usual cause of prominent eosinophilia','Other blood-count abnormalities are more characteristic.'),('Routine pyogenic bacteremia as the most specific explanation','Marked eosinophilia points toward other infectious and noninfectious mechanisms.')],
 'Eosinophilia is a mechanistic clue rather than a final diagnosis', '**Larval tissue migration can provoke eosinophilia.**',['Acute schistosomiasis is relevant after compatible freshwater exposure.','Drug reactions and noninfectious eosinophilic disorders remain alternatives.'], '**Choose tests according to the stage of infection.**',['Early stool or urine egg testing can be negative before patency.','Do not assume every parasite causes eosinophilia.'],[['Tissue-invasive helminth','Important association'],['Exposure','Fresh water and travel region'],['Testing','Stage-appropriate serology or direct detection']],[TR],style='clinical_scenario')
q('A patient receiving intensive chemotherapy has fever and an ANC of 0.2 × 10^9/L. Which approach is most appropriate?', 'Obtain suitable cultures promptly and start urgent empirical antibiotics with antipseudomonal coverage, without waiting for culture results',[
 ('Observe until a focal sign appears','Neutropenia can blunt local inflammatory findings.'),('Delay therapy until the organism is identified','This can permit rapid deterioration.'),('Treat with an oral agent lacking relevant Gram-negative coverage regardless of risk','Initial treatment must match severity and neutropenic infection risk.')],
 'Febrile neutropenia is a time-sensitive emergency', '**Severe neutropenia impairs containment of invasive infection.**',['Collect peripheral and relevant central-line cultures when feasible.','Use local resistance history, allergies and organ function to select therapy.'], '**Assess instability and the need for inpatient care immediately.**',['Low-risk outpatient management requires a validated assessment and reliable follow-up.','Shock or major comorbidity excludes a casual outpatient approach.'],[['Immediate','Cultures without treatment delay'],['Empirical therapy','Appropriate antipseudomonal regimen'],['Disposition','Risk and stability assessment']],[NF],style='clinical_scenario')

if __name__=='__main__':print('Fever approach: '+str(len(rows))+' questions drafted')
